def formule(cible):
    import pandas as pd
    from scipy import stats
    df = pd.DataFrame(cible)
    colonnes_num = [c for c in df.columns if pd.api.types.is_numeric_dtype(df[c])]
    if len(colonnes_num) < 2:
        return None
    paire = df[[colonnes_num[0], colonnes_num[1]]].apply(pd.to_numeric, errors='coerce').dropna()
    if len(paire) < 2:
        return None
    resultat = stats.pearsonr(paire[colonnes_num[0]], paire[colonnes_num[1]])
    return {
        'colonnes': [colonnes_num[0], colonnes_num[1]],
        'coefficient': float(resultat.statistic),
        'p_value': float(resultat.pvalue),
    }

