def formule(cible):
    import pandas as pd
    from prophet import Prophet
    df = pd.DataFrame(cible)
    colonnes_date = [c for c in df.columns if pd.api.types.is_datetime64_any_dtype(df[c])]
    colonnes_num = [c for c in df.columns if pd.api.types.is_numeric_dtype(df[c])]
    if not colonnes_date or not colonnes_num:
        return None
    entrainement = pd.DataFrame({
        'ds': pd.to_datetime(df[colonnes_date[0]]),
        'y': pd.to_numeric(df[colonnes_num[0]], errors='coerce'),
    }).dropna()
    if len(entrainement) < 3:
        return None
    modele = Prophet()
    modele.fit(entrainement)
    futur = modele.make_future_dataframe(periods=7)
    prevision = modele.predict(futur).tail(7)
    return [
        {'date': str(row.ds.date()), 'valeur_prevue': float(row.yhat)}
        for row in prevision.itertuples()
    ]

