import numpy

NOM = "regression_logistique_np"


def entrainer(X, y, lr=0.1, epochs=200, seed=42, on_epoch=None):
    X = numpy.asarray(X, dtype=float)
    y = numpy.asarray(y, dtype=float).reshape(-1)
    mu, sd = X.mean(axis=0), X.std(axis=0) + 1e-9
    Z = (X - mu) / sd
    w, b, acc = numpy.zeros(Z.shape[1]), 0.0, 0.0
    for epoch in range(epochs):
        p = 1.0 / (1.0 + numpy.exp(-(Z @ w + b)))
        w = w - lr * (Z.T @ (p - y)) / len(y)
        b = b - lr * float(numpy.mean(p - y))
        acc = float(numpy.mean((p > 0.5) == (y > 0.5)))
        perte = float(-numpy.mean(y * numpy.log(p + 1e-9) + (1 - y) * numpy.log(1 - p + 1e-9)))
        if on_epoch and on_epoch(epoch, {"loss": perte, "accuracy": acc}):
            break
    return {"weights": {"w": w, "mu": mu, "sd": sd, "b": numpy.array([b])},
            "config": {"n_features": int(Z.shape[1])}, "accuracy": acc}


def predire(weights, config, X):
    Z = (numpy.asarray(X, dtype=float) - weights["mu"]) / weights["sd"]
    return (1.0 / (1.0 + numpy.exp(-(Z @ weights["w"] + weights["b"][0]))) > 0.5).astype(int)

