# ── Example of a valid document script (provided for guidance) ────────────
# This script illustrates EXACTLY the 10-key structure expected by the
# document channel, AND the DYNAMIC DISCOVERY method for the data: it does not
# reference ANY specific slug hard-coded, it iterates over enregistrement.items() and
# distinguishes numeric/textual/date by a type test — exactly what the
# ABSOLUTE RULE requires. It is complete and directly executable as is on
# any table (no error, no missing key), which makes it
# a neutral safety net if the model cannot do better.
# The model must take inspiration from it for the FORM, adapting the actual content
# (title, lines, totals) to the business meaning of the table described in the SCHEMA.

def executer(enregistrement):
    from datetime import date, datetime

    # 1. Dynamic discovery of the fields — no hard-coded key.
    champs_texte = {}
    champs_nombre = {}
    champs_date = {}
    for cle, valeur in enregistrement.items():
        if cle in ("id", "matricule", "code_acces_client") or valeur is None:
            continue
        if isinstance(valeur, bool):
            champs_texte[cle] = "Oui" if valeur else "Non"
        elif isinstance(valeur, (int, float)):
            champs_nombre[cle] = valeur
        elif isinstance(valeur, str) and valeur.strip():
            # Dates arrive as text (YYYY-MM-DD or DD/MM/YYYY): recognized by their format.
            analysee = None
            for forme in ("%Y-%m-%d", "%d/%m/%Y"):
                try:
                    analysee = datetime.strptime(valeur.strip()[:10], forme)
                    break
                except ValueError:
                    pass
            if analysee:
                champs_date[cle] = analysee
            else:
                champs_texte[cle] = valeur.strip()

    # 2. Identity — first text value found serves as "name" for lack of
    #    anything better; failing that, a generic identifier based on the id.
    identifiant = enregistrement.get("id")
    premier_texte = next(iter(champs_texte.values()), None)
    nom_entite = premier_texte or (f"Entity #{identifiant}" if identifiant is not None else "Entity")

    # 3. Lines — one line per numeric field discovered (quantity by
    #    default 1, the unit price = the value itself).
    lignes = []
    for cle, valeur in champs_nombre.items():
        lignes.append({
            "description":   cle.replace("_", " ").capitalize(),
            "quantite":      1,
            "prix_unitaire": round(float(valeur), 2),
            "montant":       round(float(valeur), 2),
        })
    if not lignes:
        lignes.append({
            "description":   "No numeric data available on this record",
            "quantite":      0,
            "prix_unitaire": 0.0,
            "montant":       0.0,
        })

    sous_total = round(sum(l["montant"] for l in lignes), 2)

    # 4. Date — first date discovered, otherwise today.
    premiere_date = next(iter(champs_date.values()), None)
    if isinstance(premiere_date, (date, datetime)):
        date_document = premiere_date.strftime("%d/%m/%Y")
    else:
        date_document = date.today().strftime("%d/%m/%Y")

    # 5. Notes — real condition on the discovered data, never
    #    fixed text that would not depend on the record.
    if not champs_nombre and not champs_texte:
        notes = "Record without usable data: document generated for guidance."
    elif len(lignes) == 1 and lignes[0]["montant"] == 0.0:
        notes = "No numeric amount found on this record."
    else:
        notes = f"Document generated automatically from {len(champs_nombre)} numeric value(s) and {len(champs_texte)} text value(s)."

    return {
        "type_document": "autre",
        "titre":         f"Document — {nom_entite}",
        "reference":     f"REF-{identifiant}" if identifiant is not None else "REF-0000",
        "date":          date_document,
        "emetteur": {
            "nom":     "",
            "adresse": "",
            "contact": "",
        },
        "destinataire": {
            "nom":     nom_entite,
            "adresse": "",
            "contact": "",
        },
        "lignes": lignes,
        "totaux": {
            "sous_total": sous_total,
            "tva":        0.0,
            "total":      sous_total,
        },
        "notes":     notes,
        "pied_page": "",
    }

