    if enr_id:
        from engine.models import Enregistrement
        lignes = Enregistrement.objects.filter(id=enr_id)
        if ENTREPRISE_ID is not None:
            lignes = lignes.filter(table__entreprise_id=ENTREPRISE_ID)
        enr = lignes.first()
        if enr is not None:
            resume = f"Record {enr_id} processed ({len(enr.to_dict())} fields)"
