-- To be run by the PostgreSQL administrator (never by the application). Adapt the names to the project.
-- 1. The application role can only add audit rows.
REVOKE UPDATE, DELETE, TRUNCATE ON engine_journalaudit FROM {role};
GRANT SELECT, INSERT ON engine_journalaudit TO {role};
REVOKE UPDATE, DELETE, TRUNCATE ON engine_blocsysteme FROM {role};
GRANT SELECT, INSERT ON engine_blocsysteme TO {role};
-- 2. Even for a role that would have these rights: a trigger that refuses any modification or deletion.
CREATE OR REPLACE FUNCTION siem_ajout_seul() RETURNS trigger AS $$
BEGIN
  IF current_setting('siem.purge', true) = 'oui' THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'append-only table (SIEM)';
END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS siem_audit_ajout_seul ON engine_journalaudit;
CREATE TRIGGER siem_audit_ajout_seul BEFORE UPDATE OR DELETE ON engine_journalaudit FOR EACH ROW EXECUTE FUNCTION siem_ajout_seul();
DROP TRIGGER IF EXISTS siem_bloc_ajout_seul ON engine_blocsysteme;
CREATE TRIGGER siem_bloc_ajout_seul BEFORE UPDATE OR DELETE ON engine_blocsysteme FOR EACH ROW EXECUTE FUNCTION siem_ajout_seul();
-- 3. The signed retention purge goes through an administration role that first runs: SET siem.purge = 'oui';
